function uniqueValues(key) {
  return [...new Set(PLAN_DATA.plans.map((row) => row[key]).filter(Boolean))].sort((a, b) => String(a).localeCompare(String(b), "zh-CN"));
}

function createFilter(config) {
  const root = document.getElementById(config.id);
  root.innerHTML = `
    <span class="filter-label">${config.label}</span>
    <div class="filter-shell">
      <button class="filter-button" type="button" aria-expanded="false">
        <span class="filter-text">全部</span><span>⌄</span>
      </button>
      <div class="filter-menu">
        <input type="search" placeholder="搜索${config.label}">
        <div class="option-list"></div>
      </div>
    </div>
  `;

  const button = root.querySelector(".filter-button");
  const menu = root.querySelector(".filter-menu");
  const search = root.querySelector("input");
  const list = root.querySelector(".option-list");

  function renderOptions() {
    const query = search.value.trim().toLowerCase();
    const values = uniqueValues(config.key).filter((value) => String(value).toLowerCase().includes(query));
    list.innerHTML = values.map((value) => {
      const checked = state[config.stateKey].has(value) ? "checked" : "";
      return `<label class="option-row"><input type="checkbox" value="${escapeHtml(value)}" ${checked}> <span>${escapeHtml(value)}</span></label>`;
    }).join("");
  }

  button.addEventListener("click", () => {
    document.querySelectorAll(".filter-menu.is-open").forEach((node) => {
      if (node !== menu) node.classList.remove("is-open");
    });
    menu.classList.toggle("is-open");
    button.setAttribute("aria-expanded", menu.classList.contains("is-open"));
    renderOptions();
    search.focus();
  });

  search.addEventListener("input", renderOptions);
  list.addEventListener("change", (event) => {
    if (event.target.type !== "checkbox") return;
    const value = event.target.value;
    if (event.target.checked) state[config.stateKey].add(value);
    else state[config.stateKey].delete(value);
    updateFilterButton(config);
    render();
  });

  renderOptions();
  updateFilterButton(config);
}

function updateFilterButton(config) {
  const root = document.getElementById(config.id);
  const text = root.querySelector(".filter-text");
  const count = state[config.stateKey].size;
  text.textContent = count ? `已选 ${count}` : "全部";
}

function escapeHtml(value) {
  return String(value ?? "").replace(/[&<>"']/g, (char) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#039;",
  }[char]));
}

function formatNumber(value, digits = 0) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return "-";
  return numeric.toLocaleString("zh-CN", { maximumFractionDigits: digits, minimumFractionDigits: digits });
}

function formatCompactMoney(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return "-";
  if (Math.abs(numeric) >= 100000000) return `${formatNumber(numeric / 100000000, 2)}亿`;
  if (Math.abs(numeric) >= 10000) return `${formatNumber(numeric / 10000, 1)}万`;
  return formatNumber(numeric, 0);
}

function toNumber(value) {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : 0;
}

function theoreticalTurnoverDays(detail) {
  const major = detail["大类"];
  if (major === "油" || major === "电" || major === "轮") return 30;
  if (major === "配") return accessoryTurnoverDays[detail["预算品类"]] ?? 90;
  return 30;
}

function theoreticalInventoryCost(detail) {
  const outbound30 = toNumber(detail["近30天出库成本"]);
  const normalInventory = outbound30 / 30 * theoreticalTurnoverDays(detail);
  const inTransit = toNumber(detail["内部在途成本"]);
  const frozen = toNumber(detail["冻结成本"]);
  const unhealthy = detail["大类"] === "配" ? toNumber(detail["不健康库存成本"]) * 0.5 : 0;
  return normalInventory + inTransit + frozen + unhealthy;
}

function detailsForRows(rows) {
  const rowKeys = new Set(rows.map((row) => `${row["大类"]}||${row["预算品类"]}||${row["预算品牌"]}`));
  return PLAN_DATA.details.filter((detail) => rowKeys.has(`${detail["大类"]}||${detail["预算品类"]}||${detail["预算品牌"]}`));
}

function filteredInventoryRows() {
  const keyword = state.keyword.trim().toLowerCase();
  return (PLAN_DATA.inventoryRows || []).filter((row) => {
    if (state.selectedMajor.size && !state.selectedMajor.has(row["大类"])) return false;
    if (state.selectedCategory.size && !state.selectedCategory.has(row["预算品类"])) return false;
    if (state.selectedBrand.size && !state.selectedBrand.has(row["预算品牌"])) return false;
    if (keyword) {
      const haystack = `${row["大类"]} ${row["预算品类"]} ${row["预算品牌"]}`.toLowerCase();
      if (!haystack.includes(keyword)) return false;
    }
    return true;
  });
}

function otherBrandInventoryCost() {
  if (state.selectedBrand.size && !state.selectedBrand.has("其他")) return 0;
  return (PLAN_DATA.otherBrandInventoryRows || [])
    .filter((row) => {
      if (state.selectedMajor.size && !state.selectedMajor.has(row["大类"])) return false;
      if (state.selectedCategory.size && !state.selectedCategory.has(row["预算品类"])) return false;
      return row["预算品牌"] === "其他";
    })
    .reduce((sum, row) => sum + toNumber(row["库存成本"]), 0);
}

function formatMetricValue(detail, fallbackStatus) {
  const option = metricOptions.find((item) => item.label === state.metric) || metricOptions[0];
  if (!option.field) return fallbackStatus || "";
  const raw = detail?.[option.field];
  const numeric = Number(raw);
  if (!Number.isFinite(numeric)) return "-";
  if (option.type === "percent") return `${formatNumber(numeric * 100, option.digits)}%`;
  return formatNumber(numeric, option.digits);
}

function statusClass(value) {
  if (value === "备货") return "status-stock";
  if (value === "部分备货" || value === "计划备货") return "status-partial";
  return "status-none";
}

function getFilteredRows() {
  const keyword = state.keyword.trim().toLowerCase();
  return PLAN_DATA.plans.filter((row) => {
    if (state.selectedMajor.size && !state.selectedMajor.has(row["大类"])) return false;
    if (state.selectedCategory.size && !state.selectedCategory.has(row["预算品类"])) return false;
    if (state.selectedBrand.size && !state.selectedBrand.has(row["预算品牌"])) return false;
    if (keyword) {
      const haystack = `${row["大类"]} ${row["预算品类"]} ${row["预算品牌"]}`.toLowerCase();
      if (!haystack.includes(keyword)) return false;
    }
    if (state.status === "有备货" && Number(row["建议备货仓数"] || 0) === 0) return false;
    if (state.status === "有退出" && Number(row["建议退出仓数"] || 0) === 0) return false;
    return true;
  });
}

function renderSummary(rows) {
  const stock = rows.reduce((sum, row) => sum + Number(row["建议备货仓数"] || 0), 0);
  const exits = rows.reduce((sum, row) => sum + Number(row["建议退出仓数"] || 0), 0);
  const sourceInventoryRows = filteredInventoryRows();
  const currentCost = sourceInventoryRows.reduce((sum, detail) => sum + toNumber(detail["库存成本"]), 0);
  const theoreticalCost = sourceInventoryRows.reduce((sum, detail) => sum + theoreticalInventoryCost(detail), 0);
  const otherBrandCost = otherBrandInventoryCost();
  document.getElementById("rowCount").textContent = formatNumber(rows.length);
  document.getElementById("stockCount").textContent = formatNumber(stock);
  document.getElementById("exitCount").textContent = formatNumber(exits);
  document.getElementById("avgStock").textContent = rows.length ? formatNumber(stock / rows.length, 1) : "0";
  document.getElementById("currentInventoryCost").textContent = formatCompactMoney(currentCost);
  document.getElementById("theoreticalInventoryCost").textContent = formatCompactMoney(theoreticalCost);
  document.getElementById("inventoryGap").textContent = formatCompactMoney(currentCost - theoreticalCost);
  document.getElementById("otherBrandInventoryCost").textContent = formatCompactMoney(otherBrandCost);
  document.getElementById("resultTitle").textContent = `当前结果：${rows.length} 个品类品牌`;
}

function renderChips() {
  const chips = [];
  filters.forEach((filter) => {
    state[filter.stateKey].forEach((value) => chips.push(`<span class="chip">${escapeHtml(filter.label)}：${escapeHtml(value)}</span>`));
  });
  if (state.keyword) chips.push(`<span class="chip">搜索：${escapeHtml(state.keyword)}</span>`);
  if (state.status !== "全部") chips.push(`<span class="chip">状态：${escapeHtml(state.status)}</span>`);
  if (state.metric !== "备货规划") chips.push(`<span class="chip">单元格指标：${escapeHtml(state.metric)}</span>`);
  document.getElementById("chips").innerHTML = chips.join("");
}

function renderPlanningNotes() {
  document.getElementById("sourceName").textContent = PLAN_DATA.source || "";
  document.getElementById("planningRules").innerHTML = (PLAN_DATA.rules || []).map((rule) => `
    <div class="rule-item">
      <span class="rule-name">${escapeHtml(rule["规则"] || "")}</span>
      <span class="rule-desc">${escapeHtml(rule["说明"] || "")}</span>
    </div>
  `).join("");
}

function setupMetricSelect() {
  const select = document.getElementById("metricSelect");
  select.innerHTML = metricOptions.map((option) => `<option value="${escapeHtml(option.label)}">${escapeHtml(option.label)}</option>`).join("");
  select.value = state.metric;
  select.addEventListener("change", () => {
    state.metric = select.value;
    render();
  });
}

function groupSpans() {
  const spans = [];
  let current = null;
  centerNames.forEach((name) => {
    const item = PLAN_DATA.centers.find((center) => center.name === name);
    const groupName = `组${item?.group ?? "-"}`;
    if (!current || current.name !== groupName) {
      current = { name: groupName, count: 1 };
      spans.push(current);
    } else {
      current.count += 1;
    }
  });
  return spans;
}

function renderTable(rows) {
  const table = document.getElementById("planTable");
  if (!rows.length) {
    table.innerHTML = `<tbody><tr><td class="empty-state">没有匹配结果</td></tr></tbody>`;
    return;
  }

  const groupCells = groupSpans().map((group) => `<th colspan="${group.count}">${escapeHtml(group.name)}</th>`).join("");
  const centerCells = centerNames.map((center) => `<th>${escapeHtml(center)}</th>`).join("");
  const body = rows.map((row, rowIndex) => {
    const statusCells = centerNames.map((center) => {
      const value = row[center] || "";
      const detail = detailMap.get(`${row["大类"]}||${row["预算品类"]}||${row["预算品牌"]}||${center}`) || {};
      const displayValue = formatMetricValue(detail, value);
      const adjusted = detail["是否调整"] === "是";
      const adjustedClass = adjusted ? "status-adjusted" : "";
      const title = adjusted ? `品类经理规划：${detail["品类经理规划"] || "-"}；最终规划：${detail["最终规划"] || value}` : "";
      return `<td class="status-cell ${statusClass(value)} ${adjustedClass}" title="${escapeHtml(title)}" data-row="${rowIndex}" data-center="${escapeHtml(center)}">${escapeHtml(displayValue)}</td>`;
    }).join("");
    return `
      <tr>
        <td class="sticky-col sticky-1">${escapeHtml(row["大类"])}</td>
        <td class="sticky-col sticky-2">${escapeHtml(row["预算品类"])}</td>
        <td class="sticky-col sticky-3">${escapeHtml(row["预算品牌"])}</td>
        <td class="count-col">${formatNumber(row["原备货仓数"])}</td>
        <td class="count-col">${formatNumber(row["建议备货仓数"])}</td>
        <td class="count-col">${formatNumber(row["建议退出仓数"])}</td>
        ${statusCells}
      </tr>
    `;
  }).join("");

  table.innerHTML = `
    <thead>
      <tr class="group-head">
        <th class="sticky-col sticky-1"></th>
        <th class="sticky-col sticky-2"></th>
        <th class="sticky-col sticky-3"></th>
        <th colspan="3">仓数</th>
        ${groupCells}
      </tr>
      <tr class="column-head">
        <th class="sticky-col sticky-1">大类</th>
        <th class="sticky-col sticky-2">预算品类</th>
        <th class="sticky-col sticky-3">预算品牌</th>
        <th>原备货</th>
        <th>建议备货</th>
        <th>建议退出</th>
        ${centerCells}
      </tr>
    </thead>
    <tbody>${body}</tbody>
  `;

  table.querySelectorAll(".status-cell").forEach((cell) => {
    cell.addEventListener("click", () => {
      const row = rows[Number(cell.dataset.row)];
      openDetail(row, cell.dataset.center);
    });
  });
}

function renderMobileResults(rows) {
  const container = document.getElementById("mobileResults");
  if (!rows.length) {
    container.innerHTML = `<div class="empty-state">没有匹配结果</div>`;
    return;
  }

  container.innerHTML = rows.map((row, rowIndex) => {
    const centerCells = centerNames.map((center) => {
      const status = row[center] || "";
      const detail = detailMap.get(`${row["大类"]}||${row["预算品类"]}||${row["预算品牌"]}||${center}`) || {};
      const displayValue = formatMetricValue(detail, status);
      const adjustedClass = detail["是否调整"] === "是" ? "status-adjusted" : "";
      return `
        <button class="mobile-center-cell ${statusClass(status)} ${adjustedClass}" type="button" data-row="${rowIndex}" data-center="${escapeHtml(center)}">
          <span class="mobile-center-name">${escapeHtml(center)}</span>
          <span class="mobile-center-value">${escapeHtml(displayValue)}</span>
        </button>
      `;
    }).join("");
    return `
      <article class="mobile-card">
        <div class="mobile-card-head">
          <div class="mobile-card-title">${escapeHtml(row["预算品类"])} · ${escapeHtml(row["预算品牌"])}</div>
          <div class="mobile-card-sub">${escapeHtml(row["大类"])}</div>
          <div class="mobile-card-metrics">
            <span class="mobile-pill">原备货 ${formatNumber(row["原备货仓数"])}</span>
            <span class="mobile-pill">建议备货 ${formatNumber(row["建议备货仓数"])}</span>
            <span class="mobile-pill">建议退出 ${formatNumber(row["建议退出仓数"])}</span>
          </div>
        </div>
        <div class="mobile-center-grid">${centerCells}</div>
      </article>
    `;
  }).join("");

  container.querySelectorAll(".mobile-center-cell").forEach((cell) => {
    cell.addEventListener("click", () => {
      const row = rows[Number(cell.dataset.row)];
      openDetail(row, cell.dataset.center);
    });
  });
}

function openDetail(row, center) {
  const detail = detailMap.get(`${row["大类"]}||${row["预算品类"]}||${row["预算品牌"]}||${center}`) || {};
  const status = row[center] || detail["最终规划"] || "";
  const theoryCost = theoreticalInventoryCost(detail);
  const metricRows = (items) => items.map((item) => `
    <div class="metric-row">
      <span class="metric-name">${escapeHtml(item.label)}</span>
      <span class="metric-value">${escapeHtml(item.value)}</span>
    </div>
  `).join("");
  const demandMetrics = [
    { label: "近30天出库成本", value: formatNumber(detail["近30天出库成本"], 0) },
    { label: "订货门店数/总服务门店数", value: `${formatNumber((detail["订货门店数/总服务门店数"] || 0) * 100, 1)}%` },
    { label: "近90天动销率", value: `${formatNumber((detail["近90天动销率"] || 0) * 100, 1)}%` },
    { label: "出库去重 SKU 数", value: formatNumber(detail["出库去重sku数"], 0) },
    { label: "近30天入库成本", value: formatNumber(detail["近30天入库成本"], 0) },
  ];
  const healthMetrics = [
    { label: "销售周转", value: formatNumber(detail["销售周转"], 1) },
    { label: "出库周转", value: formatNumber(detail["出库周转"], 1) },
    { label: "不健康库存占比", value: `${formatNumber((detail["不健康库存占比"] || 0) * 100, 1)}%` },
    { label: "不健康库存成本", value: formatNumber(detail["不健康库存成本"], 0) },
    { label: "内部在途成本", value: formatNumber(detail["内部在途成本"], 0) },
    { label: "冻结成本", value: formatNumber(detail["冻结成本"], 0) },
    { label: "坏件成本", value: formatNumber(detail["坏件成本"], 0) },
  ];
  document.getElementById("detailCenter").textContent = `${center}｜中心仓组 ${detail["中心仓分组"] ?? "-"}`;
  document.getElementById("detailTitle").textContent = `${row["预算品类"]} · ${row["预算品牌"]}`;
  document.getElementById("detailBody").innerHTML = `
    <span class="status-badge ${statusClass(status)}">${escapeHtml(status)}</span>
    <div class="detail-grid">
      <div class="detail-item"><label>品类经理规划</label><strong>${escapeHtml(detail["品类经理规划"] || "-")}</strong></div>
      <div class="detail-item"><label>最终规划</label><strong>${escapeHtml(detail["最终规划"] || status || "-")}</strong></div>
      <div class="detail-item"><label>规划得分</label><strong>${formatNumber(detail["规划得分"], 1)}</strong></div>
      <div class="detail-item"><label>需求得分</label><strong>${formatNumber(detail["需求得分"], 1)}</strong></div>
      <div class="detail-item"><label>库存健康得分</label><strong>${formatNumber(detail["库存健康得分"], 1)}</strong></div>
      <div class="detail-item"><label>备货等级</label><strong>${escapeHtml(detail["备货等级"] || "-")}</strong></div>
      <div class="detail-item"><label>当前库存成本</label><strong>${formatNumber(detail["库存成本"], 0)}</strong></div>
      <div class="detail-item"><label>理论库存成本</label><strong>${formatNumber(theoryCost, 0)}</strong></div>
    </div>
    <div class="reason">${escapeHtml(detail["规划原因"] || "暂无说明")}</div>
    <div class="metric-section">
      <h3>需求得分指标明细</h3>
      <div class="metric-list">${metricRows(demandMetrics)}</div>
    </div>
    <div class="metric-section">
      <h3>库存健康得分指标明细</h3>
      <div class="metric-list">${metricRows(healthMetrics)}</div>
    </div>
  `;
  document.getElementById("detailPanel").classList.add("is-open");
  document.getElementById("detailPanel").setAttribute("aria-hidden", "false");
  document.getElementById("panelBackdrop").classList.add("is-open");
}

function closeDetail() {
  document.getElementById("detailPanel").classList.remove("is-open");
  document.getElementById("detailPanel").setAttribute("aria-hidden", "true");
  document.getElementById("panelBackdrop").classList.remove("is-open");
}

function exportCsv(rows) {
  const headers = ["大类", "预算品类", "预算品牌", "原备货仓数", "建议备货仓数", "建议退出仓数", ...centerNames];
  const lines = [headers.join(",")].concat(rows.map((row) => headers.map((header) => `"${String(row[header] ?? "").replace(/"/g, '""')}"`).join(",")));
  const blob = new Blob(["\ufeff" + lines.join("\n")], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = "中心仓品类品牌规划_当前筛选.csv";
  link.click();
  URL.revokeObjectURL(url);
}

function render() {
  const rows = getFilteredRows();
  renderSummary(rows);
  renderChips();
  renderTable(rows);
  renderMobileResults(rows);
  return rows;
}

filters.forEach(createFilter);

document.getElementById("keywordInput").addEventListener("input", (event) => {
  state.keyword = event.target.value;
  render();
});

document.querySelectorAll(".segment").forEach((button) => {
  button.addEventListener("click", () => {
    document.querySelectorAll(".segment").forEach((node) => node.classList.remove("is-active"));
    button.classList.add("is-active");
    state.status = button.dataset.status;
    render();
  });
});

document.getElementById("resetFilters").addEventListener("click", () => {
  state.selectedMajor.clear();
  state.selectedCategory.clear();
  state.selectedBrand.clear();
  state.keyword = "";
  state.status = "全部";
  state.metric = "备货规划";
  document.getElementById("keywordInput").value = "";
  document.getElementById("metricSelect").value = state.metric;
  document.querySelectorAll(".segment").forEach((node) => node.classList.toggle("is-active", node.dataset.status === "全部"));
  filters.forEach(updateFilterButton);
  render();
});

document.getElementById("exportCsv").addEventListener("click", () => exportCsv(getFilteredRows()));
document.getElementById("closePanel").addEventListener("click", closeDetail);
document.getElementById("panelBackdrop").addEventListener("click", closeDetail);
document.addEventListener("click", (event) => {
  if (!event.target.closest(".filter-shell")) {
    document.querySelectorAll(".filter-menu.is-open").forEach((node) => node.classList.remove("is-open"));
  }
});

renderPlanningNotes();
setupMetricSelect();
render();
